import type { HTMLAttributes } from "astro/types"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const variants = cva(
  "text-muted-foreground **:data-[slot=kbd]:bg-muted-foreground/10 h-auto gap-1 py-2 text-xs/relaxed font-medium group-data-[disabled=true]/input-group:opacity-50 **:data-[slot=kbd]:rounded-[calc(var(--radius-sm)-2px)] **:data-[slot=kbd]:px-1 **:data-[slot=kbd]:text-[0.625rem] [&>svg:not([class*='size-'])]:size-3.5 flex cursor-text items-center justify-center select-none",
  {
    variants: {
      align: {
        "inline-start":
          "pl-2 has-[>button]:ml-[-0.275rem] has-[>kbd]:ml-[-0.275rem] order-first has-[>a]:-ml-1",
        "inline-end":
          "pr-2 has-[>button]:mr-[-0.275rem] has-[>kbd]:mr-[-0.275rem] order-last has-[>a]:-mr-1",
        "block-start":
          "px-2 pt-2 group-has-[>input]/input-group:pt-2 [.border-b]:pb-2 order-first w-full justify-start",
        "block-end":
          "px-2 pb-2 group-has-[>input]/input-group:pb-2 [.border-t]:pt-2 order-last w-full justify-start",
      },
    },
    defaultVariants: {
      align: "inline-start",
    },
  }
)

type Props = HTMLAttributes<"div"> & VariantProps<typeof variants>

const { class: className, align = "inline-start", ...props } = Astro.props
---

<div
  role="group"
  data-slot="input-group-addon"
  data-align={align}
  class={cn(variants({ align }), className)}
  {...props}
>
  <slot />
</div>

---
import type { HTMLAttributes } from "astro/types"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { Button, type ButtonVariantProps } from "@/components/ui/button"

const variants = cva("gap-2 rounded-md text-xs/relaxed flex items-center shadow-none", {
  variants: {
    size: {
      xs: "h-5 gap-1 rounded-[calc(var(--radius-sm)-2px)] px-1 [&>svg:not([class*='size-'])]:size-3",
      sm: "",
      "icon-xs": "size-6 p-0 has-[>svg]:p-0",
      "icon-sm": "size-7 p-0 has-[>svg]:p-0",
    },
  },
  defaultVariants: {
    size: "xs",
  },
})

type Props = VariantProps<typeof variants> &
  HTMLAttributes<"button"> &
  HTMLAttributes<"a"> & {
    type?: "button" | "submit" | "reset"
    variant?: ButtonVariantProps["variant"]
  }

const {
  class: className,
  type = "button",
  variant = "ghost",
  size = "xs",
  ...props
} = Astro.props

const isLink = "href" in Astro.props
---

<Button
  data-size={size}
  type={isLink ? undefined : type}
  variant={variant}
  class={cn(variants({ size }), className)}
  {...props}
>
  <slot />
</Button>

