import type { ComponentProps } from "astro/types"

import { cn } from "@/lib/utils"
import { Input } from "@/components/ui/input"

type Props = ComponentProps<typeof Input>

const {
  class: className,
  "data-slot": dataSlot = "input-group-control",
  ...props
} = Astro.props
---

<Input
  data-slot={dataSlot}
  class={cn("rounded-none border-0 bg-transparent shadow-none ring-0 focus-visible:ring-0 aria-invalid:ring-0 dark:bg-transparent h-full flex-1", className)}
  {...props}
/>
